<html><head><style>
@page { margin: 28px; } body { font: 9px DejaVu Sans; color: #172033; } table { width: 100%; border-collapse: collapse; } th,td { padding: 6px; vertical-align: top; } .grid th,.grid td { border: 1px solid #64748b; } .grid th { background: #f1f5f9; } .right { text-align: right; } .head { border-bottom: 3px solid {{ $render['setting']->brand_color }}; } .premium_elegant { border: 2px solid #b58b4a; padding: 18px; } .compact_detailed_gst { font-size: 8px; } .modern_split_panel .meta { background: #eef6f5; } .executive_corporate_gst .head { background: #102a43; color: white; padding: 10px; } .items thead { display: table-header-group; } .items tr { page-break-inside: avoid; } .avoid { page-break-inside: avoid; }
