></tr></thead><tbody>@foreach($render['tax_rows'] as $row)<tr><td>{{ $row['hsn_sac'] }}</td><td class="right">{{ number_format($row['taxable'],2) }}</td><td class="right">{{ number_format($row['tax_rate'],3) }}%</td><td class="right">{{ $row['cgst'] ? number_format($row['cgst_rate'],3).'% / '.number_format($row['cgst'],2) : '—' }}</td><td class="right">{{ $row['sgst'] ? number_format($row['sgst_rate'],3).'% / '.number_format($row['sgst'],2) : '—' }}</td><td class="right">{{ $row['igst'] ? number_format($row['igst_rate'],3).'% / '.number_format($row['igst'],2) : '—' }}</td><td class="right">{{ $row['cess'] ?: '—' }}</td><td class="right">{{ number_format($row['total_tax'],2) }}</td></tr>@endforeach</tbody></table><table style="margin-top:12px"><tr><td width="56%">@if($invoice->terms_conditions)<b>Terms</b><br>{{ $invoice->terms_conditions }}@endif @if($render['payment_qr_data_uri'])<div class="avoid" style="margin-top:12px"><img src="{{ $render['payment_qr_data_uri'] }}" alt="Payment QR" width="104" height="104"><br><b>Scan to pay {{ $invoice->currency }} {{ number_format((float)$invoice->balance_due,2) }}</b></div>@endif</td><td><table class="grid"><tr><td>Taxable</td><td class="right">{{ number_format((float)$invoice->taxable_total,2) }}</td></tr><tr><td>CGST / SGST / IGST / Cess</td><td class="right">{{ number_format((float)$invoice->cgst_total,2) }} / {{ number_format((float)$invoice->sgst_total,2) }} / {{ number_format((float)$invoice->igst_total,2) }} / {{ number_format((float)$invoice->cess_total,2) }}</td></tr><tr><td><b>Invoice total</b></td><td class="right"><b>{{ $invoice->currency }} {{ number_format((float)$invoice->grand_total,2) }}</b></td></tr><tr><td>Received</td><td class="right">{{ number_format((float)$invoice->amount_paid,2) }}</td></tr>@if($render['balance']['available'])<tr><td>Previous outstanding</td><td class="right">{{ number_format((float)$render['balance']['previous_outstanding'],2) }}</td></tr>@endif<tr><td><b>Current balance</b></td><td class="right"><b>{{ number_format((float)$render['balance']['current_balance'],2) }}</b></td></tr></table></td></tr></table></div></div></body></html>
